properties.query:
let alertWindow = 15m;
let seqWindow = 5m;
let minFrames = 3;
let sizeGate = 5000000;
UAVSarPayload_CL
| where TimeGenerated > ago(alertWindow)
| summarize FrameCount = count(), TotalBytes = sum(SizeBytes), FirstFrame = min(TimeGenerated), LastFrame = max(TimeGenerated)
    by UAVId, TimeBin = bin(TimeGenerated, seqWindow)
| where FrameCount >= minFrames and TotalBytes > sizeGate
| extend TriggerReason = strcat("작전정보탈취_SAR프레임대량생성스테이징의심_", UAVId, "_", tostring(FrameCount), "프레임")
| extend Severity = "High"
| project TimeGenerated = LastFrame, UAVId, FirstFrame, FrameCount, TotalBytes, TriggerReason, Severity
| order by TimeGenerated desc
